SELECT 
FROM sys_file_metadata
WHERE status = 1

    AND original_name LIKE CONCAT('%', #{condition.originalName}, '%')


    AND storage_type = #{condition.storageType}


    AND business_type = #{condition.businessType}


    AND business_id = #{condition.businessId}


    AND uploader_id = #{condition.uploaderId}


    AND group_id = #{condition.groupId}


    AND mime_type LIKE CONCAT(#{condition.mimeType}, '%')


    AND is_private = #{condition.isPrivate}


    AND (is_private = 0 OR uploader_id = #{currentUserId})

ORDER BY upload_time DESC

SELECT FROM sys_file_metadata WHERE status = 1 AND business_type = #{businessType} AND business_id = #{businessId}
AND (is_private = 0 OR uploader_id = #{currentUserId})
ORDER BY upload_time DESC
